import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 综合复习与自测 · 第46–54课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第二册：实践与进步 · 综合复习与自测 · 第46–54课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-2/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第37–45课","link":"/life/english/new-concept/book-2/review-part-05"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第55–63课","link":"/life/english/new-concept/book-2/review-part-07"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第37–45课","link":"/life/english/new-concept/book-2/review-part-05"},"next":{"text":"第二册：实践与进步 · 综合复习与自测 · 第55–63课","link":"/life/english/new-concept/book-2/review-part-07"}},"headers":[],"relativePath":"life/english/new-concept/book-2/review-part-06.md","filePath":"life/english/new-concept/book-2/review-part-06.md"}'),n={name:"life/english/new-concept/book-2/review-part-06.md"};function r(l,e,i,p,c,d){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-综合复习与自测-·-第46–54课" tabindex="-1">第二册：实践与进步 · 综合复习与自测 · 第46–54课 <a class="header-anchor" href="#第二册-实践与进步-·-综合复习与自测-·-第46–54课" aria-label="Permalink to &quot;第二册：实践与进步 · 综合复习与自测 · 第46–54课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-46-·-数量表达与范围" tabindex="-1">Lesson 46 · 数量表达与范围 <a class="header-anchor" href="#lesson-46-·-数量表达与范围" aria-label="Permalink to &quot;Lesson 46 · 数量表达与范围 {#lesson-46-·-数量表达与范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The overnight train cost more but offered fewer comfortable seats.</p><h3 id="练习-1-45" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-45" aria-label="Permalink to &quot;练习 1 {#练习-1-45}&quot;">​</a></h3><p>选 less/fewer：The carriage had ___ seats.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fewer</p><p><strong>解析：</strong> seats 是可数复数名词。</p></details><p><strong>表达迁移：</strong> 比较两种交通选择，写费用、座位和最终决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The overnight train cost more but offered fewer comfortable seats. We changed to a daytime service on the return trip. It was cheaper and gave us a better view.</p><p>第一句的组织方式：cost 是过去式，与原形同形；more 省略比较中的 money，fewer 修饰可数复数 seats。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：fewer comfort 不对，comfort 通常不可数；可说 less comfort 或 fewer comfortable seats。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-046">回看本课</a></p><h2 id="lesson-47-·-间接引语与视角转换" tabindex="-1">Lesson 47 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-47-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 47 · 间接引语与视角转换 {#lesson-47-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The cellar was said to be haunted, but no one had evidence.</p><h3 id="练习-1-46" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-46" aria-label="Permalink to &quot;练习 1 {#练习-1-46}&quot;">​</a></h3><p>补全：The house was said ___ be empty.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> be said to do 是报道被动结构。</p></details><p><strong>表达迁移：</strong> 写一段传闻调查，先标明说法，再写观察结果与处理行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The cellar was said to be haunted, but no one had evidence. A camera later recorded a loose window opening in the wind. The owner repaired its latch.</p><p>第一句的组织方式：was said to be 是被动报道结构；but no one had evidence 限定传闻可信度，不确认鬼魂存在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：evidence 通常不可数，不写 an evidence；可说 a piece of evidence。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-047">回看本课</a></p><h2 id="lesson-48-·-时间、原因与让步从句" tabindex="-1">Lesson 48 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-48-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 48 · 时间、原因与让步从句 {#lesson-48-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> As soon as the dentist removed the mirror, I asked a question.</p><h3 id="练习-1-47" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-47" aria-label="Permalink to &quot;练习 1 {#练习-1-47}&quot;">​</a></h3><p>选连接词：___ she finished speaking, I replied.（一……就……）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> As soon as</p><p><strong>解析：</strong> 该连接词准确表达紧接发生。</p></details><p><strong>表达迁移：</strong> 写一次不方便说话时的交流，说明非语言回应和随后提出的问题。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>As soon as the dentist removed the mirror, I asked a question. I wanted to know when I could eat. She gave me clear instructions before I left.</p><p>第一句的组织方式：As soon as 从句给出先发生的动作，主句 asked 紧接其后；两者都是具体过去事件。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：while he removed the mirror 不一定等于拿开之后；表达紧接应使用 as soon as。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-048">回看本课</a></p><h2 id="lesson-49-·-叙事中的时态与衔接" tabindex="-1">Lesson 49 · 叙事中的时态与衔接 <a class="header-anchor" href="#lesson-49-·-叙事中的时态与衔接" aria-label="Permalink to &quot;Lesson 49 · 叙事中的时态与衔接 {#lesson-49-·-叙事中的时态与衔接}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was sleeping on the terrace when a gust blew my blanket away.</p><h3 id="练习-1-48" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-48" aria-label="Permalink to &quot;练习 1 {#练习-1-48}&quot;">​</a></h3><p>填 blow 的过去式：A gust ___ my blanket away.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blew</p><p><strong>解析：</strong> blow 的过去式不规则变化为 blew。</p></details><p><strong>表达迁移：</strong> 写一个被天气打断的小计划，包含初衷、意外与实际结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was sleeping on the terrace when a gust blew my blanket away. I woke up and carried the bed indoors. My plan to sleep under the stars lasted only an hour.</p><p>第一句的组织方式：was sleeping 是背景，when 引出 blew；blow 的过去式为 blew，away 表离开原处。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">回看本课</a></p><h2 id="lesson-50-·-过去完成时与先后关系" tabindex="-1">Lesson 50 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-50-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 50 · 过去完成时与先后关系 {#lesson-50-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time I asked, the bus had passed my stop.</p><h3 id="练习-1-49" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-49" aria-label="Permalink to &quot;练习 1 {#练习-1-49}&quot;">​</a></h3><p>填 pass：The bus had ___ my stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> passed</p><p><strong>解析：</strong> had 后用过去分词 passed。</p></details><p><strong>表达迁移：</strong> 讲一次坐过站经历，用过去完成时说明发现问题前已经发生的事。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By the time I asked, the bus had passed my stop. The driver showed me the return route. I bought another ticket and checked every stop.</p><p>第一句的组织方式：By the time 从句 asked 定位过去时刻，had passed 说明更早已发生的事件；my stop 是目的站。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：get out of 常用于小汽车，get off 常用于公共汽车；不能在所有交通方式中机械互换。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-050">回看本课</a></p><h2 id="lesson-51-·-完成进行时与持续活动" tabindex="-1">Lesson 51 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-51-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 51 · 完成进行时与持续活动 {#lesson-51-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Tess has been avoiding sweet snacks for two weeks.</p><h3 id="练习-1-50" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-50" aria-label="Permalink to &quot;练习 1 {#练习-1-50}&quot;">​</a></h3><p>填 for/since：She has been practising ___ two weeks.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> for</p><p><strong>解析：</strong> two weeks 是一段时长。</p></details><p><strong>表达迁移：</strong> 描述坚持某个生活习惯的过程，交代持续时间和一次选择。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Tess has been avoiding sweet snacks for two weeks. Today she chose fruit at the café. She said the conversation was a better reward than cake.</p><p>第一句的组织方式：has been avoiding 是完成进行时，for two weeks 是持续长度，sweet snacks 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-051">回看本课</a></p><h2 id="lesson-52-·-现在完成时与过去时间" tabindex="-1">Lesson 52 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-52-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 52 · 现在完成时与过去时间 {#lesson-52-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Fallen leaves have covered the path outside our classroom.</p><h3 id="练习-1-51" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-51" aria-label="Permalink to &quot;练习 1 {#练习-1-51}&quot;">​</a></h3><p>填 have/has：Fallen leaves ___ covered the path.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> leaves 是复数，配 have。</p></details><p><strong>表达迁移：</strong> 写三句校园环境变化，区分观察到的结果和已经完成的清理。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Fallen leaves have covered the path outside our classroom. We collected them in two large bags. A narrow strip is now safe to walk on.</p><p>第一句的组织方式：Fallen leaves 是复数主语，have covered 为完成时；outside our classroom 修饰 path。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：leaves 是 leaf 的复数；不能写 leafs 来表示这里的树叶。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-052">回看本课</a></p><h2 id="lesson-53-·-被动语态与信息重点" tabindex="-1">Lesson 53 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-53-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 53 · 被动语态与信息重点 {#lesson-53-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The power failure was caused by a damaged wire.</p><h3 id="练习-1-52" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-52" aria-label="Permalink to &quot;练习 1 {#练习-1-52}&quot;">​</a></h3><p>填 by/from：The failure was caused ___ a damaged wire.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> by</p><p><strong>解析：</strong> be caused by 引出导致事件的原因。</p></details><p><strong>表达迁移：</strong> 写一份非技术故障说明，交代确认原因、发现位置和恢复条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The power failure was caused by a damaged wire. An engineer found it behind a panel. The building remained closed until the repair was complete.</p><p>第一句的组织方式：failure 为单数主语，was caused 是过去被动，by 引出原因；damaged 是过去分词作定语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：caused from 不合常见搭配；被动原因用 caused by。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-053">回看本课</a></p><h2 id="lesson-54-·-时间、原因与让步从句" tabindex="-1">Lesson 54 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-54-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 54 · 时间、原因与让步从句 {#lesson-54-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> As soon as I opened the jar, jam ran over my fingers.</p><h3 id="练习-1-53" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-53" aria-label="Permalink to &quot;练习 1 {#练习-1-53}&quot;">​</a></h3><p>填 run 的过去式：Jam ___ over my fingers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> ran</p><p><strong>解析：</strong> 具体过去动作使用 ran。</p></details><p><strong>表达迁移：</strong> 描写厨房里连锁发生的两件小意外，用一个紧接关系连接词。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>As soon as I opened the jar, jam ran over my fingers. I reached for a cloth with my clean hand. Unfortunately, the cloth knocked over a cup.</p><p>第一句的组织方式：As soon as 引出开罐动作，ran 为 run 的过去式；over my fingers 描述流过的表面。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：run 的过去式是 ran，过去分词才是 run；不能在简单过去叙事中写 jam run。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-054">回看本课</a></p>',76)])])}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
